import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
void main()=>runApp(const App());
class App extends StatelessWidget{const App({super.key});@override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,home:const Home());}
class Home extends StatefulWidget{const Home({super.key});@override State<Home> createState()=>_Home();}
class _Home extends State<Home>{static const ch=MethodChannel('dfsupport/notifications');List rows=[];Future<void> load()async{final r=await ch.invokeMethod<List>('getNotifications')??[];setState(()=>rows=r.reversed.toList());}Future<void> settings()=>ch.invokeMethod('openNotificationAccess');@override void initState(){super.initState();load();}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('DFSupport')),body:Padding(padding:const EdgeInsets.all(16),child:Column(children:[const Text('通知取得デバッグ'),const SizedBox(height:8),Row(children:[Expanded(child:FilledButton(onPressed:load,child:const Text('通知履歴を更新'))),const SizedBox(width:8),Expanded(child:OutlinedButton(onPressed:settings,child:const Text('通知アクセス設定')))]),const SizedBox(height:8),const Text('Uber案件が届いた直後に更新してください。Uber以外の通知も記録してListener自体が動いているか確認します。'),const Divider(),Expanded(child:rows.isEmpty?const Center(child:Text('取得した通知はありません')):ListView.builder(itemCount:rows.length,itemBuilder:(_,i){final m=Map.from(rows[i]);return Card(child:Padding(padding:const EdgeInsets.all(12),child:SelectableText('アプリ: ${m['package']}\nタイトル: ${m['title']}\n本文: ${m['text']}\n追加: ${m['bigText']}\n時刻: ${m['time']}')));}))]))));}}
